"""Migrated Meridian CRM 4.2 order validation rules."""

from decimal import Decimal, InvalidOperation


def _value(row: dict | None, column: str) -> str:
    """Return a field value, treating missing or None values as empty strings."""
    if not row:
        return ""
    value = row.get(column, "")
    return "" if value is None else str(value)


def _number(value: object) -> Decimal:
    """Apply legacy numeric coercion: blank and missing values compare as zero."""
    if value is None or value == "":
        return Decimal(0)
    try:
        return Decimal(str(value))
    except (InvalidOperation, ValueError):
        return Decimal(0)


def _lookup(
    tables: dict | None,
    table_name: str,
    key_column: str,
    key_value: str,
    output_column: str,
) -> str:
    """Implement legacy LOOKUP, including soft-delete invisibility."""
    if tables is None:
        return ""

    rows = tables.get(table_name, [])
    for row in rows:
        if not isinstance(row, dict):
            continue
        if _value(row, "DEL_FLG") == "Y":
            continue
        if _value(row, key_column) == key_value:
            return _value(row, output_column)
    return ""


def validate(
    record: dict,
    old: dict | None = None,
    event: str = "INSERT",
    tables: dict | None = None,
    table: str = "ORD_HEADER",
) -> list[dict]:
    """Validate an order header or order line using the migrated VRL rules."""
    errors: list[dict] = []
    record = record or {}
    old_record = old or {}

    def add_error(code: str, message: str) -> None:
        errors.append(
            {
                "code": code,
                "message": message,
                "severity": "BLOCK",
            }
        )

    if table == "ORD_HEADER":
        if event in ("INSERT", "UPDATE"):
            disc_pct = _number(record.get("DISC_PCT", ""))
            if not (disc_pct >= 0 and disc_pct <= 100):
                add_error("E5001", "Discount out of range")

        if event == "UPDATE":
            disc_pct = _number(record.get("DISC_PCT", ""))
            owner_uid = _value(record, "OWNER_UID")
            role_id = _lookup(
                tables, "USR_MASTER", "USR_ID", owner_uid, "ROLE_ID"
            )
            if disc_pct > 20 and role_id != "MGR" and role_id != "ADMIN":
                add_error(
                    "E5002",
                    "Discount over 20 percent requires manager role",
                )

        if event == "UPDATE":
            old_status = _value(old_record, "STAT_CD")
            status = _value(record, "STAT_CD")
            if old_status == "I" and status != "I" and status != "X":
                add_error("E5003", "Invoiced order can only be cancelled")

    elif table == "ORD_LINE":
        if event in ("INSERT", "UPDATE"):
            qty = _number(record.get("QTY", ""))
            if not qty > 0:
                add_error("E5004", "Quantity must be positive")

        if event == "INSERT":
            prod_id = _value(record, "PROD_ID")
            active_flag = _lookup(
                tables, "PROD_MASTER", "PROD_ID", prod_id, "ACTIVE_FLG"
            )
            if active_flag != "Y":
                add_error("E5005", "Product not active")

    return errors


def is_blocked(errors: list[dict]) -> bool:
    """Return whether at least one validation failure blocks the write."""
    return any(error.get("severity") == "BLOCK" for error in errors)
